import{_ as a,o as i,c as t,ag as s}from"./chunks/framework.BwSLX4ak.js";const k=JSON.parse('{"title":"Installation and deployment","description":"","frontmatter":{},"headers":[],"relativePath":"en/shitbot/installation.md","filePath":"en/shitbot/installation.md"}'),n={name:"en/shitbot/installation.md"};function o(l,e,r,d,h,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="installation-and-deployment" tabindex="-1">Installation and deployment <a class="header-anchor" href="#installation-and-deployment" aria-label="Permalink to &quot;Installation and deployment&quot;">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>ShitBot needs a QQ bot implementation that supports OneBot v11 forward WebSocket. The plugin initiates the connection; it does not accept reverse WebSocket connections.</p><p>Use <a href="https://github.com/LLOneBot/LuckyLilliaBot" target="_blank" rel="noreferrer">LuckyLilliaBot</a> or another compatible implementation. Prepare:</p><ul><li>A OneBot forward WebSocket address.</li><li>The OneBot access token, if authentication is enabled.</li><li>The QQ group IDs allowed to use the bot.</li><li>A ShitBot JAR matching your platform.</li></ul><h2 id="choose-a-platform-jar" tabindex="-1">Choose a platform JAR <a class="header-anchor" href="#choose-a-platform-jar" aria-label="Permalink to &quot;Choose a platform JAR&quot;">​</a></h2><p>Download from <a href="https://github.com/hutuyee/ShitBot/releases" target="_blank" rel="noreferrer">GitHub Releases</a>:</p><table tabindex="0"><thead><tr><th>Platform</th><th>JAR</th><th>Minimum plugin runtime Java</th></tr></thead><tbody><tr><td>Bukkit servers such as Spigot, Paper, Folia, and CatServer</td><td><code>ShitBotSpigot-*.jar</code></td><td>Java 8+</td></tr><tr><td>BungeeCord</td><td><code>ShitBotBungee-*.jar</code></td><td>Java 8+</td></tr><tr><td>Velocity</td><td><code>ShitBotVelocity-*.jar</code></td><td>Java 21+</td></tr><tr><td>Nukkit-MOT</td><td><code>ShitBotNukkit-*.jar</code></td><td>Java 17+</td></tr></tbody></table><p>These are ShitBot&#39;s bytecode requirements. Your server software may require a newer Java version, which must also be satisfied. If a release has no JAR for your platform, that build was not published. Do not substitute a JAR for another platform.</p><h2 id="first-startup" tabindex="-1">First startup <a class="header-anchor" href="#first-startup" aria-label="Permalink to &quot;First startup&quot;">​</a></h2><ol><li>Stop the server or proxy.</li><li>Place the matching JAR in that instance&#39;s <code>plugins/</code> directory.</li><li>Start the instance and wait for ShitBot to create its data directory.</li><li>Stop the instance.</li><li>Open the generated <code>config.yml</code>, <code>commands.yml</code>, <code>lang/</code> files, and <code>templates/default.yml</code>.</li><li>Complete the minimal configuration below and start again.</li></ol><p>Do not edit default configuration inside the JAR. When later versions add settings, back up your configuration and compare it with newly generated defaults.</p><h2 id="minimal-onebot-configuration" tabindex="-1">Minimal OneBot configuration <a class="header-anchor" href="#minimal-onebot-configuration" aria-label="Permalink to &quot;Minimal OneBot configuration&quot;">​</a></h2><p>Edit <code>config.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">language</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;en_US&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">onebot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  websocket-url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ws://127.0.0.1:3001&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  access-token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allow-all-groups</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed-group-ids</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456789</span></span></code></pre></div><p><code>language: &quot;en_US&quot;</code> enables the English messages and aliases used in this guide. Keep <code>zh_CN</code> to use Chinese.</p><ul><li>On the same machine, use <code>ws://127.0.0.1:&lt;port&gt;</code>.</li><li>Between hosts, use <code>wss://</code> and ensure Java trusts the server certificate.</li><li><code>access-token</code> must match OneBot&#39;s configuration.</li><li>If <code>allowed-group-ids</code> is empty and <code>allow-all-groups: false</code>, all group messages are rejected.</li><li><code>allow-all-groups: true</code> is not recommended for production.</li></ul><p>After startup, run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/shitbot status</span></span></code></pre></div><p>Confirm that the database and OneBot connection are healthy before enabling forwarding, binding, images, or shortcuts.</p><h2 id="a-single-bukkit-server" tabindex="-1">A single Bukkit server <a class="header-anchor" href="#a-single-bukkit-server" aria-label="Permalink to &quot;A single Bukkit server&quot;">​</a></h2><p>Install only <code>ShitBotSpigot-*.jar</code> and keep:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">deployment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  role</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;standalone&quot;</span></span></code></pre></div><p>The Spigot plugin connects directly to OneBot. A single instance can use the default SQLite database or MySQL. No <code>backend-transport</code> configuration is needed.</p><h2 id="a-bungeecord-or-velocity-network" tabindex="-1">A BungeeCord or Velocity network <a class="header-anchor" href="#a-bungeecord-or-velocity-network" aria-label="Permalink to &quot;A BungeeCord or Velocity network&quot;">​</a></h2><p>For group chat forwarding, QQ binding, and proxy features, install <code>ShitBotBungee-*.jar</code> or <code>ShitBotVelocity-*.jar</code> on the proxy.</p><p>To query a backend&#39;s TPS, run backend shortcuts from QQ, or save inventory snapshots on backends:</p><ol><li>Install the matching edition on the proxy.</li><li>Install the Spigot edition on each target Bukkit backend.</li><li>Set each backend&#39;s <code>deployment.role</code> to <code>backend</code>.</li><li>Connect the proxy and every backend to the same MySQL database.</li><li>Configure the authenticated command channel in <code>commands.yml</code>.</li></ol><p>See <a href="/docs/en/shitbot/proxy-backend.html">Proxies and backend servers</a> for the full procedure.</p><h2 id="a-single-nukkit-mot-server" tabindex="-1">A single Nukkit-MOT server <a class="header-anchor" href="#a-single-nukkit-mot-server" aria-label="Permalink to &quot;A single Nukkit-MOT server&quot;">​</a></h2><p>Place <code>ShitBotNukkit-*.jar</code> in Nukkit-MOT&#39;s <code>plugins/</code> directory. Nukkit-MOT runs as a standalone platform:</p><ul><li>It does not use <code>deployment.role</code>.</li><li>It does not use the proxy/backend command channel.</li><li>TPS queries and QQ shortcuts always run locally.</li><li>It supports SQLite and MySQL.</li><li>It does not use the PictureBridge client protocol; media labels retain the original URL.</li></ul><h2 id="enable-chat-forwarding" tabindex="-1">Enable chat forwarding <a class="header-anchor" href="#enable-chat-forwarding" aria-label="Permalink to &quot;Enable chat forwarding&quot;">​</a></h2><p>Both directions are disabled by default. Enable them independently in <code>config.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">forwarding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  game-to-group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    require-prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#qq &quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  group-to-game</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    require-prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#mc &quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    media-mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;browser&quot;</span></span></code></pre></div><p>Default usage:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Minecraft: #qq message to the QQ group</span></span>
<span class="line"><span>QQ group:  #mc message to the game</span></span></code></pre></div><p>Run <code>/shitbot reload</code> after editing. See <a href="/docs/en/shitbot/configuration.html">Configuration</a> for more options.</p><h2 id="after-installation" tabindex="-1">After installation <a class="header-anchor" href="#after-installation" aria-label="Permalink to &quot;After installation&quot;">​</a></h2><p>Suggested checks:</p><ol><li><code>/shitbot status</code> reports an available database.</li><li>OneBot is connected.</li><li>The bot&#39;s group is in <code>allowed-group-ids</code>.</li><li>Sending <code>server status</code> with <code>en_US</code> (or <code>服务器状态</code> with <code>zh_CN</code>) gets a reply.</li><li>After enabling forwarding, both <code>#qq</code> and <code>#mc</code> work as intended.</li><li>In a proxy/backend deployment, <code>TPS &lt;backend-name&gt;</code> reaches the selected backend.</li></ol><p>See <a href="/docs/en/shitbot/troubleshooting.html">Troubleshooting</a> if something goes wrong.</p>`,42)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
